// Command platgen writes internal/plat's two generated files from
// internal/win's exported API:
//
//   - win_windows.go forwards every name to internal/win (type aliases,
//     constants, error values and thin functions), so Windows runs exactly
//     the code it ran before plat existed;
//   - stub_other.go declares the same names for other systems, each function
//     doing nothing and answering ErrUnsupported when it can return an error.
//
// A name that a hand-written file in internal/plat already declares for a
// system is left out of that system's generated file, so the stubs shrink as
// the Linux code (docs/ROADMAP.md, section 9) replaces them.
//
// Run it from the repository's root after adding to internal/win:
//
//	go run ./tools/platgen
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/build"
	"go/format"
	"go/importer"
	"go/parser"
	"go/printer"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const (
	winPath  = "lootnest/internal/win"
	platDir  = "internal/plat"
	fwdFile  = "win_windows.go"
	stubFile = "stub_other.go"
	header   = "// Code generated by tools/platgen from internal/win; DO NOT EDIT.\n\n"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "platgen:", err)
		os.Exit(1)
	}
}

func run() error {
	build.Default.GOOS = "windows"
	build.Default.CgoEnabled = false
	fset := token.NewFileSet()
	pkg, err := importer.ForCompiler(fset, "source", nil).(types.ImporterFrom).ImportFrom(winPath, ".", 0)
	if err != nil {
		return err
	}
	inits, err := errorInits(fset)
	if err != nil {
		return err
	}
	ownWin, err := declared("windows")
	if err != nil {
		return err
	}
	ownOther, err := declared("linux")
	if err != nil {
		return err
	}

	var names []string
	for _, n := range pkg.Scope().Names() {
		if token.IsExported(n) {
			names = append(names, n)
		}
	}
	sort.Strings(names)

	fwd := newFile("windows")
	stub := newFile("!windows")
	fwd.imports[winPath] = "win"
	for _, n := range names {
		obj := pkg.Scope().Lookup(n)
		if !ownWin[n] {
			if err := fwd.forward(obj); err != nil {
				return err
			}
		}
		if !ownOther[n] && !windowsOnly(obj) {
			if err := stub.stub(obj, inits, ownOther); err != nil {
				return err
			}
		}
	}
	if err := fwd.write(filepath.Join(platDir, fwdFile)); err != nil {
		return err
	}
	return stub.write(filepath.Join(platDir, stubFile))
}

// errorInits reads internal/win's source for the text of each exported
// error value, so a stub says the same words.
func errorInits(fset *token.FileSet) (map[string]string, error) {
	ctx := build.Default
	dir := filepath.Join("internal", "win")
	ents, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	out := map[string]string{}
	for _, e := range ents {
		name := e.Name()
		if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		if ok, _ := ctx.MatchFile(dir, name); !ok {
			continue
		}
		f, err := parser.ParseFile(fset, filepath.Join(dir, name), nil, 0)
		if err != nil {
			return nil, err
		}
		for _, d := range f.Decls {
			g, ok := d.(*ast.GenDecl)
			if !ok || g.Tok != token.VAR {
				continue
			}
			for _, s := range g.Specs {
				vs := s.(*ast.ValueSpec)
				for i, id := range vs.Names {
					if i >= len(vs.Values) {
						continue
					}
					call, ok := vs.Values[i].(*ast.CallExpr)
					if !ok {
						continue
					}
					if sel, ok := call.Fun.(*ast.SelectorExpr); ok && fmt.Sprint(sel.X) == "errors" && sel.Sel.Name == "New" {
						var b bytes.Buffer
						printer.Fprint(&b, fset, call)
						out[id.Name] = b.String()
					}
				}
			}
		}
	}
	return out, nil
}

// declared lists what internal/plat's hand-written files declare for goos:
// top-level names, and methods as "Type.Method".
func declared(goos string) (map[string]bool, error) {
	ctx := build.Default
	ctx.GOOS = goos
	out := map[string]bool{}
	ents, err := os.ReadDir(platDir)
	if os.IsNotExist(err) {
		return out, nil
	}
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	for _, e := range ents {
		name := e.Name()
		if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") || name == fwdFile || name == stubFile {
			continue
		}
		if ok, _ := ctx.MatchFile(platDir, name); !ok {
			continue
		}
		f, err := parser.ParseFile(fset, filepath.Join(platDir, name), nil, 0)
		if err != nil {
			return nil, err
		}
		for _, d := range f.Decls {
			switch d := d.(type) {
			case *ast.FuncDecl:
				if d.Recv != nil && len(d.Recv.List) == 1 {
					t := d.Recv.List[0].Type
					if st, ok := t.(*ast.StarExpr); ok {
						t = st.X
					}
					out[fmt.Sprint(t)+"."+d.Name.Name] = true
					continue
				}
				out[d.Name.Name] = true
			case *ast.GenDecl:
				for _, s := range d.Specs {
					switch s := s.(type) {
					case *ast.TypeSpec:
						out[s.Name.Name] = true
					case *ast.ValueSpec:
						for _, id := range s.Names {
							out[id.Name] = true
						}
					}
				}
			}
		}
	}
	return out, nil
}

type file struct {
	tag     string
	imports map[string]string // path -> name
	consts  bytes.Buffer
	vars    bytes.Buffer
	body    bytes.Buffer
}

func newFile(tag string) *file { return &file{tag: tag, imports: map[string]string{}} }

// qual writes a type from internal/win as plat's own name and notes the
// other packages a declaration needs.
func (f *file) qual(p *types.Package) string {
	if p.Path() == winPath {
		return ""
	}
	f.imports[p.Path()] = p.Name()
	return p.Name()
}

func (f *file) typ(t types.Type) string { return types.TypeString(t, f.qual) }

func (f *file) forward(obj types.Object) error {
	n := obj.Name()
	switch o := obj.(type) {
	case *types.Const:
		fmt.Fprintf(&f.consts, "\t%s = win.%s\n", n, n)
	case *types.TypeName:
		fmt.Fprintf(&f.body, "type %s = win.%s\n\n", n, n)
	case *types.Var:
		if isError(o.Type()) {
			fmt.Fprintf(&f.vars, "\t%s = win.%s\n", n, n)
			return nil
		}
		fmt.Fprintf(&f.body, "// Set%s sets win.%s.\nfunc Set%s(v %s) { win.%s = v }\n\n", n, n, n, f.typ(o.Type()), n)
	case *types.Func:
		sig := o.Type().(*types.Signature)
		params, args := f.params(sig)
		call := fmt.Sprintf("win.%s(%s)", n, args)
		if sig.Results().Len() > 0 {
			call = "return " + call
		}
		fmt.Fprintf(&f.body, "func %s(%s)%s {\n\t%s\n}\n\n", n, params, f.results(sig, false), call)
	}
	return nil
}

func (f *file) stub(obj types.Object, inits map[string]string, own map[string]bool) error {
	n := obj.Name()
	switch o := obj.(type) {
	case *types.Const:
		t := ""
		if _, named := o.Type().(*types.Named); named {
			t = " " + f.typ(o.Type())
		}
		fmt.Fprintf(&f.consts, "\t%s%s = %s\n", n, t, o.Val().ExactString())
	case *types.TypeName:
		under := o.Type().Underlying()
		if st, ok := under.(*types.Struct); ok {
			var b strings.Builder
			b.WriteString("struct {\n")
			for i := 0; i < st.NumFields(); i++ {
				fl := st.Field(i)
				if !fl.Exported() {
					continue
				}
				if fl.Embedded() {
					fmt.Fprintf(&b, "\t%s\n", f.typ(fl.Type()))
					continue
				}
				fmt.Fprintf(&b, "\t%s %s\n", fl.Name(), f.typ(fl.Type()))
			}
			b.WriteString("}")
			fmt.Fprintf(&f.body, "type %s %s\n\n", n, b.String())
		} else {
			fmt.Fprintf(&f.body, "type %s %s\n\n", n, f.typ(under))
		}
		named := o.Type().(*types.Named)
		for i := 0; i < named.NumMethods(); i++ {
			m := named.Method(i)
			if !m.Exported() || own[n+"."+m.Name()] {
				continue
			}
			sig := m.Type().(*types.Signature)
			recv := n
			if _, ptr := sig.Recv().Type().(*types.Pointer); ptr {
				recv = "*" + n
			}
			params, _ := f.params(sig)
			fmt.Fprintf(&f.body, "func (%s) %s(%s)%s {%s}\n\n", recv, m.Name(), params, f.results(sig, true), stubBody(sig))
		}
	case *types.Var:
		if isError(o.Type()) {
			init := inits[n]
			if init == "" {
				init = fmt.Sprintf("errors.New(%q)", strings.ToLower(n))
			}
			f.imports["errors"] = "errors"
			fmt.Fprintf(&f.vars, "\t%s = %s\n", n, init)
			return nil
		}
		fmt.Fprintf(&f.body, "// Set%s does nothing here.\nfunc Set%s(%s) {}\n\n", n, n, f.typ(o.Type()))
	case *types.Func:
		sig := o.Type().(*types.Signature)
		params, _ := f.params(sig)
		fmt.Fprintf(&f.body, "func %s(%s)%s {%s}\n\n", n, params, f.results(sig, true), stubBody(sig))
	}
	return nil
}

// params gives a parameter list with names, and the arguments that pass
// them on.
func (f *file) params(sig *types.Signature) (string, string) {
	var ps, as []string
	for i := 0; i < sig.Params().Len(); i++ {
		p := sig.Params().At(i)
		name := p.Name()
		if name == "" || name == "_" {
			name = fmt.Sprintf("p%d", i)
		}
		t := p.Type()
		if sig.Variadic() && i == sig.Params().Len()-1 {
			ps = append(ps, name+" ..."+f.typ(t.(*types.Slice).Elem()))
			as = append(as, name+"...")
			continue
		}
		ps = append(ps, name+" "+f.typ(t))
		as = append(as, name)
	}
	return strings.Join(ps, ", "), strings.Join(as, ", ")
}

// results gives a result list; named ones let a stub return its zero
// values with a bare return.
func (f *file) results(sig *types.Signature, named bool) string {
	r := sig.Results()
	if r.Len() == 0 {
		return ""
	}
	if !named {
		if r.Len() == 1 {
			return " " + f.typ(r.At(0).Type())
		}
		var ts []string
		for i := 0; i < r.Len(); i++ {
			ts = append(ts, f.typ(r.At(i).Type()))
		}
		return " (" + strings.Join(ts, ", ") + ")"
	}
	var ts []string
	for i := 0; i < r.Len(); i++ {
		name := fmt.Sprintf("r%d", i)
		if isError(r.At(i).Type()) && i == r.Len()-1 {
			name = "err"
		}
		ts = append(ts, name+" "+f.typ(r.At(i).Type()))
	}
	return " (" + strings.Join(ts, ", ") + ")"
}

func stubBody(sig *types.Signature) string {
	r := sig.Results()
	if r.Len() == 0 {
		return ""
	}
	if isError(r.At(r.Len() - 1).Type()) {
		return "\n\terr = ErrUnsupported\n\treturn\n"
	}
	return "\n\treturn\n"
}

// windowsOnly tells a name whose type uses golang.org/x/sys/windows: it
// has no meaning elsewhere, so it gets no stub and app code using it stays
// in a _windows.go file.
func windowsOnly(obj types.Object) bool {
	found := false
	types.TypeString(obj.Type(), func(p *types.Package) string {
		if strings.HasPrefix(p.Path(), "golang.org/x/sys/windows") {
			found = true
		}
		return p.Name()
	})
	return found
}

func isError(t types.Type) bool {
	return types.Identical(t, types.Universe.Lookup("error").Type())
}

func (f *file) write(path string) error {
	var b bytes.Buffer
	b.WriteString(header)
	fmt.Fprintf(&b, "//go:build %s\n\npackage plat\n\n", f.tag)
	if len(f.imports) > 0 {
		var paths []string
		for p := range f.imports {
			paths = append(paths, p)
		}
		sort.Strings(paths)
		b.WriteString("import (\n")
		for _, p := range paths {
			fmt.Fprintf(&b, "\t%q\n", p)
		}
		b.WriteString(")\n\n")
	}
	if f.consts.Len() > 0 {
		fmt.Fprintf(&b, "const (\n%s)\n\n", f.consts.String())
	}
	if f.vars.Len() > 0 {
		fmt.Fprintf(&b, "var (\n%s)\n\n", f.vars.String())
	}
	b.Write(f.body.Bytes())
	out, err := format.Source(b.Bytes())
	if err != nil {
		os.WriteFile(path+".broken", b.Bytes(), 0o644)
		return fmt.Errorf("%s: %w (see %s.broken)", path, err, path)
	}
	return os.WriteFile(path, out, 0o644)
}
